  all.filter(dashboardIsOverdue).forEach(t=>{if(seen.has(t.id))return;action.push({t,ic:'⏰',bg:'#fff3e0',reason:'เกินกำหนดส่ง',tag:'เกินกำหนด',color:'var(--amber)'});seen.add(t.id);});
  all.filter(t=>t.status==='review').forEach(t=>{if(seen.has(t.id))return;action.push({t,ic:'👀',bg:'#eef2ff',reason:'รอตรวจ/อนุมัติ',tag:'รออนุมัติ',color:'var(--sky)'});seen.add(t.id);});
