  const risk=kpiCodes.map(c=>{const dt=all.filter(t=>t.dept===c);const bl=dt.filter(t=>t.status==='block').length;const ov=dt.filter(dashboardIsOverdue).length;const sc=deptScore(c);const reasons=[];if(sc<90)reasons.push('KPI '+sc);if(bl)reasons.push(bl+' ติดปัญหา');if(ov)reasons.push(ov+' เกินกำหนด');return {code:c,score:sc,rk:(100-sc)+bl*12+ov*8,reason:reasons.join(' · ')||'อยู่ในเกณฑ์ดี'};}).sort((a,b)=>b.rk-a.rk).slice(0,4);
  const kpiBars=kpiCodes.map(c=>({label:deptName(c),v:deptScore(c),click:`go('kpi')`})).sort((a,b)=>b.v-a.v);
